#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1 || n > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long sum = 0;
    for (long i = 1; i < n; i++) {
        if (n % i == 0) {
            sum += i;
        }
    }
    if (sum < n) {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    } else if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    }
    return 0;
}
